-- Quy uoc UUID de test (khong dung trong production):
-- 00000000-0000-XXXX-0000-00000000NNNN
-- XXXX = ma bang (1000=city, 2000=operator, 3000=bus, 4000=bus_seat,
--                 5000=route, 7000=trip, c000=location,
--                 d000=route_stop_template, e000=trip_stop,
--                 8000=app_user, 9000=booking, a000=booking_seat, b000=payment)
-- NNNN = so thu tu ban ghi (4 chu so hex)
